import{_ as e,o as r,c as t,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Calendar Card Pro","description":"German Calendar Card Pro documentation entry in the UGSo Open Source collection.","frontmatter":{"title":"Calendar Card Pro","description":"German Calendar Card Pro documentation entry in the UGSo Open Source collection."},"headers":[],"relativePath":"en/collection/calendar-card-pro/index.md","filePath":"en/collection/calendar-card-pro/index.md","lastUpdated":1793125707000}'),d={name:"en/collection/calendar-card-pro/index.md"};function o(l,a,c,i,s,h){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="calendar-card-pro" tabindex="-1">Calendar Card Pro <a class="header-anchor" href="#calendar-card-pro" aria-label="Permalink to &quot;Calendar Card Pro&quot;">​</a></h1><p>This is the collection entry for the German Calendar Card Pro documentation.</p><p>The German documentation is maintained as an unofficial translation and practical guide. The original Calendar Card Pro project and documentation remain authoritative.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>German documentation</td><td><a href="/sammlung/calendar-card-pro/">Calendar Card Pro German docs</a></td></tr><tr><td>Original project</td><td><a href="https://github.com/alexpfau/calendar-card-pro" target="_blank" rel="noreferrer">alexpfau/calendar-card-pro</a></td></tr><tr><td>Original documentation</td><td><a href="https://calendar-card-pro.alexpfau.com" target="_blank" rel="noreferrer">calendar-card-pro.alexpfau.com</a></td></tr><tr><td>Tracked source commit</td><td><a href="https://github.com/alexpfau/calendar-card-pro/commit/a3b01138daa44947f6673c33fe700e5ef4a08957" target="_blank" rel="noreferrer"><code>a3b01138daa44947f6673c33fe700e5ef4a08957</code></a></td></tr><tr><td>Release</td><td><code>v4.1.0</code></td></tr><tr><td>License</td><td>MIT</td></tr></tbody></table><p>The source files are checked daily by a scheduled GitHub Action so the German documentation can be updated when the original documentation changes.</p><details class="details custom-block"><summary>Detailed reference from the German documentation</summary><h2 id="reference-calendar-card-pro" tabindex="-1">Calendar Card Pro <a class="header-anchor" href="#reference-calendar-card-pro" aria-label="Permalink to &quot;Calendar Card Pro {#reference-calendar-card-pro}&quot;">​</a></h2><p>Calendar Card Pro is a modern, highly customizable calendar card for Home Assistant. It displays upcoming events efficiently and clearly, supporting multiple calendars, compact views, column views, weather, templates, actions, all-day event badges, per-calendar filters and a visual editor.</p><div class="warning custom-block"><p class="custom-block-title">Unofficial English documentation</p><p>This documentation is an unofficial English working translation and practical documentation. The original Calendar Card Pro project and its English documentation remain authoritative.</p></div><img src="https://raw.githubusercontent.com/alexpfau/calendar-card-pro/main/.github/img/header.png" alt="Calendar Card Pro Vorschau" width="100%"><table tabindex="0"><thead><tr><th>field</th><th>Value</th></tr></thead><tbody><tr><td>Original project</td><td><a href="https://github.com/alexpfau/calendar-card-pro" target="_blank" rel="noreferrer">alexpfau/calendar-card-pro</a></td></tr><tr><td>Original documentation</td><td><a href="https://calendar-card-pro.alexpfau.com" target="_blank" rel="noreferrer">calendar-card-pro.alexpfau.com</a></td></tr><tr><td>Checked commit</td><td><a href="https://github.com/alexpfau/calendar-card-pro/commit/a3b01138daa44947f6673c33fe700e5ef4a08957" target="_blank" rel="noreferrer"><code>a3b01138daa44947f6673c33fe700e5ef4a08957</code></a></td></tr><tr><td>Release</td><td><a href="https://github.com/alexpfau/calendar-card-pro/releases/tag/v4.1.0" target="_blank" rel="noreferrer"><code>v4.1.0</code></a></td></tr><tr><td>License</td><td><a href="https://github.com/alexpfau/calendar-card-pro/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a></td></tr><tr><td>Status</td><td>English documentation with installation, usage, features, reference, examples and change checking</td></tr></tbody></table><h3 id="inhalt" tabindex="-1">Content <a class="header-anchor" href="#inhalt" aria-label="Permalink to &quot;Content {#inhalt}&quot;">​</a></h3><ul><li><a href="/en/collection/calendar-card-pro/installation">Installation</a></li><li><a href="/en/collection/calendar-card-pro/nutzung">Usage</a></li><li><a href="/en/collection/calendar-card-pro/features">Features</a></li><li><a href="/en/collection/calendar-card-pro/konfiguration">Configuration Reference</a></li><li><a href="/en/collection/calendar-card-pro/beispiele">Examples</a></li><li><a href="/en/collection/calendar-card-pro/entwicklung">Development and Contribution</a></li><li><a href="/en/collection/calendar-card-pro/lizenz-und-stand">License and Source</a></li></ul><h3 id="wofur-ist-die-karte-gedacht" tabindex="-1">What is the card for? <a class="header-anchor" href="#wofur-ist-die-karte-gedacht" aria-label="Permalink to &quot;What is the card for? {#wofur-ist-die-karte-gedacht}&quot;">​</a></h3><p>Calendar Card Pro is intended for dashboards on which calendar events should be displayed in an easy-to-read, compact and visually clean manner. The card is particularly interesting if several calendars are to be merged, appointments should be differentiated by color according to calendar or a weekly view is needed as a column layout.</p><p>The card requires at least one home assistant entity of type <code>calendar.*</code>. According to the original, CalDAV and Google Calendar were particularly tested; in principle, the card works with integrations that provide calendar entities.</p></details>',6)])])}const f=e(d,[["render",o]]);export{u as __pageData,f as default};
